WITH valid AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, COALESCE(channel, 'N/A') AS channel_filled FROM promotions WHERE starts_on < '2023-05-11'), cleaned AS (SELECT id, channel, promo_code, ends_on, discount_pct, ADD_MONTHS(ends_on, 1) AS ends_on_plus_months, ROUND(discount_pct, 1) AS discount_pct_rounded FROM valid WHERE MONTH(ends_on) IN (2, 10, 12)), with_windows AS (SELECT *, RANK() OVER (ORDER BY discount_pct ASC) AS discount_pct_rank, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on ASC, id ASC) AS row_seq FROM cleaned), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY row_seq DESC, id ASC) AS rank_in_group FROM with_windows QUALIFY rank_in_group = 1), pivoted AS (SELECT * FROM (SELECT channel, promo_code, discount_pct FROM latest) src PIVOT (AVG(discount_pct) AS total, COUNT(1) AS item_count FOR promo_code IN ('SPRING10' AS spring10, 'BUNDLE' AS bundle))) SELECT channel, spring10_total, spring10_item_count, bundle_total FROM pivoted ORDER BY spring10_item_count DESC NULLS LAST
